package ultra.downloads;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28,qualifiers="w400dp-h800dp-mdpi") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class DL30Test {
 Activity c;
 @Before public void setup()throws Exception{c=Robolectric.buildActivity(Activity.class).setup().get();c.setTheme(android.R.style.Theme_Material_NoActionBar);app.revanced.extension.shared.utils.Utils.testContext=c;Art.network=false;Library.wiping=false;java.lang.reflect.Field f=Library.class.getDeclaredField("items");f.setAccessible(true);f.set(null,null);new File(c.getFilesDir(),"ultra_downloads_v1.json").delete();Library.prefs(c).edit().clear().commit();PlaylistIndex.invalidateCache();}
 Catalog.Track t(String id){return new Catalog.Track(id,id,"Singer","");}
 void lists()throws Exception{PlaylistPicker.add(c,"Source",Arrays.asList(t("abcdefghijk"),t("lmnopqrstuv")));PlaylistPicker.add(c,"One",Arrays.asList(t("abcdefghijk")));PlaylistPicker.add(c,"Two",Collections.<Catalog.Track>emptyList());}
 int count(String name)throws Exception{return new JSONObject(Library.prefs(c).getString("ultra_local_playlists","{}")).getJSONArray(name).length();}
 @Test public void copyToTwoKeepsSourceSkipsDuplicates()throws Exception{lists();PlaylistTransfer.transfer(c,Arrays.asList(t("abcdefghijk")),"local:Source",Arrays.asList("local:One","local:Two"),false);assertEquals(2,count("Source"));assertEquals(1,count("One"));assertEquals(1,count("Two"));}
 @Test public void moveToTwoRemovesOnlyFromCurrentSource()throws Exception{lists();PlaylistTransfer.transfer(c,Arrays.asList(t("abcdefghijk")),"local:Source",Arrays.asList("local:One","local:Two"),true);assertEquals(1,count("Source"));assertEquals(1,count("One"));assertEquals(1,count("Two"));assertTrue(PlaylistIndex.members(c,"local:Source").contains("lmnopqrstuv"));}
 @Test public void invalidDestinationLeavesSourceAndOtherDestinationUnchanged()throws Exception{lists();String before=Library.prefs(c).getString("ultra_local_playlists","");try{PlaylistTransfer.transfer(c,Arrays.asList(t("lmnopqrstuv")),"local:Source",Arrays.asList("local:Two","local:missing"),true);fail();}catch(JSONException ok){}assertEquals(before,Library.prefs(c).getString("ultra_local_playlists",""));}
 @Test public void staleSourceAndSameDestinationAreRejected()throws Exception{lists();for(List<String> dest:Arrays.asList(Arrays.asList("local:Source"),Arrays.asList("local:One"))){String before=Library.prefs(c).getString("ultra_local_playlists","");try{PlaylistTransfer.transfer(c,Arrays.asList(t("zzzzzzzzzzz")),"local:Source",dest,true);fail();}catch(JSONException ok){}assertEquals(before,Library.prefs(c).getString("ultra_local_playlists",""));}assertFalse(PlaylistTransfer.movable(c,UnmatchedDownloads.ID));assertFalse(PlaylistTransfer.movable(c,""));}
 @Test public void localCopyEditsNeverTouchOnlineSnapshot()throws Exception{lists();PlaylistIndex.register("VLPLtest","Online source");PlaylistIndex.record("PLtest",Arrays.asList(t("abcdefghijk"),t("lmnopqrstuv")),true);PlaylistIndex.groups(c);String raw=PlaylistIndex.read(c).toString();PlaylistTransfer.transfer(c,Arrays.asList(t("abcdefghijk")),"PLtest",Arrays.asList("local:Two"),true);assertEquals(raw,PlaylistIndex.read(c).toString());assertFalse(PlaylistIndex.members(c,"PLtest").contains("abcdefghijk"));assertEquals(1,count("Two"));}
 @Test public void defaultsHiddenAndToggleRestoresWithoutManualHideLoss()throws Exception{Library.Item voice=Library.add(c,"abcdefghijk","Voice 023");voice.imported=true;voice.state="done";Library.Item song=Library.add(c,"lmnopqrstuv","Kesariya");song.state="done";Library.save(c);assertFalse(VoiceRecordings.showing(c));assertFalse(VoiceRecordings.visible(c,voice));assertTrue(VoiceRecordings.visible(c,song));VoiceRecordings.set(c,true);assertTrue(VoiceRecordings.visible(c,voice));voice.hidden=true;VoiceRecordings.set(c,false);VoiceRecordings.set(c,true);assertFalse(VoiceRecordings.visible(c,voice));assertEquals(2,Library.all(c).size());}
 @Test public void recordingsPersistAndSourcesRecognized()throws Exception{assertTrue(VoiceRecordings.named("PTT-20261122-WA0001.opus",""));assertTrue(VoiceRecordings.named("Meeting.m4a","Recordings/Voice Recorder/"));assertTrue(VoiceRecordings.named("Call recording 123.m4a",""));assertFalse(VoiceRecordings.named("Kesariya.mp3","Music/"));assertFalse(VoiceRecordings.named("My voice is strong.mp3","Music/"));Library.Item i=new Library.Item();i.imported=true;i.recording=true;assertTrue(VoiceRecordings.isRecording(Library.Item.parse(i.json())));i.imported=false;assertFalse(VoiceRecordings.isRecording(i));}
 @Test public void hiddenRecordingsDoNotReappearAsMissingPlaylistRows()throws Exception{Library.Item voice=Library.add(c,"abcdefghijk","Voice 023");voice.imported=true;voice.state="done";Library.save(c);PlaylistPicker.add(c,"Source",Arrays.asList(t(voice.id)));assertEquals(0,PlaylistIndex.ordered(c,"local:Source",new ArrayList<Library.Item>(),true).size());VoiceRecordings.set(c,true);assertEquals(1,PlaylistIndex.ordered(c,"local:Source",Library.all(c),true).size());}
 void invoke(Object o,String name)throws Exception{java.lang.reflect.Method m=o.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(o);}
 View tagged(View v,String tag){if(tag.equals(v.getTag()))return v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){View found=tagged(((ViewGroup)v).getChildAt(n),tag);if(found!=null)return found;}return null;}
 void clear(View v){v.setScrollIndicators(0);if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++)clear(((ViewGroup)v).getChildAt(n));}
 void force(DownloadsScreen s)throws Exception{java.lang.reflect.Method m=DownloadsScreen.class.getDeclaredMethod("render",boolean.class);m.setAccessible(true);m.invoke(s,true);}
 void png(View v,String name)throws Exception{clear(v);v.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(760,View.MeasureSpec.EXACTLY));v.layout(0,0,400,760);Bitmap b=Bitmap.createBitmap(400,760,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));new File("qa").mkdirs();try(FileOutputStream out=new FileOutputStream("qa/"+name+".png")){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
 @Test public void realSettingsSwitchFiltersImmediatelyAndStaysSaved()throws Exception{Library.Item voice=Library.add(c,"abcdefghijk","Voice 023");voice.imported=true;voice.state="done";Library.Item song=Library.add(c,"lmnopqrstuv","Kesariya");song.state="done";Library.save(c);FrameLayout mount=new FrameLayout(c);c.setContentView(mount);DownloadsScreen s=new DownloadsScreen(c,mount,new Intent());force(s);assertEquals(1,DL29UiTest.findList(mount).getCount());png(mount,"DL30-hidden");invoke(s,"settings");AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();Switch toggle=(Switch)tagged(d.getWindow().getDecorView(),"show_voice_recordings");assertNotNull(toggle);assertFalse(toggle.isChecked());png(d.getWindow().getDecorView(),"DL30-settings-off");toggle.performClick();assertTrue(VoiceRecordings.showing(c));assertEquals(2,DL29UiTest.findList(mount).getCount());png(d.getWindow().getDecorView(),"DL30-settings-on");d.dismiss();png(mount,"DL30-shown");s.destroy();FrameLayout next=new FrameLayout(c);DownloadsScreen reopened=new DownloadsScreen(c,next,new Intent());force(reopened);assertEquals(2,DL29UiTest.findList(next).getCount());reopened.destroy();}
 @Test public void transferPickerMultiSelectAndCancelDoNotWrite()throws Exception{lists();String before=Library.prefs(c).getString("ultra_local_playlists","");PlaylistTransfer.show(c,Arrays.asList(t("abcdefghijk")),"local:Source",new Runnable(){public void run(){}});AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals("Move",d.getButton(-3).getText().toString());assertEquals(2,d.getListView().getCount());png(d.getWindow().getDecorView(),"DL30-transfer");d.getButton(-2).performClick();assertEquals(before,Library.prefs(c).getString("ultra_local_playlists",""));}
}
